import sys
from collections import deque
data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = [list(row) for row in data[2:2 + r]]
groups = 0
for i in range(r):
    for j in range(c):
        if g[i][j] == "1":
            groups += 1
            g[i][j] = "0"
            q = deque([(i, j)])
            while q:
                x, y = q.popleft()
                for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= nx < r and 0 <= ny < c and g[nx][ny] == "1":
                        g[nx][ny] = "0"
                        q.append((nx, ny))
print(groups)

