    for (int i = 0; i < r; i++) g[i] = t[p++].toCharArray();
    int groups = 0; int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1}; ArrayDeque<int[]> q = new ArrayDeque<>();
    for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) if (g[i][j] == '1') {
      groups++; g[i][j] = '0'; q.add(new int[]{i, j});
      while (!q.isEmpty()) { int[] cur = q.poll();
        for (int d = 0; d < 4; d++) { int nx = cur[0] + dx[d], ny = cur[1] + dy[d];
          if (nx >= 0 && nx < r && ny >= 0 && ny < c && g[nx][ny] == '1') { g[nx][ny] = '0'; q.add(new int[]{nx, ny}); } } } }
    System.out.println(groups);
  }
}

